    OILConflict.addVectorOf(LEFT_IDS: LEFT_IDS, &fbb)
    OILConflict.addVectorOf(RIGHT_IDS: RIGHT_IDS, &fbb)
    OILConflict.add(SHAPE: SHAPE, &fbb)
    OILConflict.add(REASON: REASON, &fbb)
    return OILConflict.endOILConflict(&fbb, start: __start)
  }

  public static func verify<T>(_ verifier: inout Verifier, at position: Int, of type: T.Type) throws where T: Verifiable {
    var _v = try verifier.visitTable(at: position)
    try _v.visit(field: VT.LEFT_IDS, fieldName: "LEFT_IDS", required: false, type: ForwardOffset<Vector<ForwardOffset<String>, String>>.self)
    try _v.visit(field: VT.RIGHT_IDS, fieldName: "RIGHT_IDS", required: false, type: ForwardOffset<Vector<ForwardOffset<String>, String>>.self)
